import 'package:flutter/material.dart';import '../services/moment_service.dart';import '../widgets/moment_card.dart';
class SearchScreen extends StatefulWidget{final MomentService service;const SearchScreen({super.key,required this.service});@override State<SearchScreen> createState()=>_S();}
class _S extends State<SearchScreen>{String q='';@override Widget build(BuildContext context){final list=widget.service.search(q);return Scaffold(appBar:AppBar(title:const Text('Search Orbia',style:TextStyle(fontWeight:FontWeight.w900))),body:Padding(padding:const EdgeInsets.all(18),child:Column(children:[TextField(autofocus:true,onChanged:(v)=>setState(()=>q=v),decoration:const InputDecoration(prefixIcon:Icon(Icons.search_rounded),hintText:'Trip, birthday, launch...')),const SizedBox(height:16),Expanded(child:ListView.separated(itemCount:list.length,separatorBuilder:(_,__)=>const SizedBox(height:10),itemBuilder:(_,i){final m=list[i];return MomentCard(moment:m,onFavorite:()=>widget.service.toggleFavorite(m.id),onSave:()=>widget.service.toggleSaved(m.id),onDelete:()async{await widget.service.delete(m.id);if(mounted)setState((){});});}))])));}}
